[{"name_path": "LECG.Commands/AssignMaterialCommand/Execute", "kind": "Method", "relative_path": "src/Commands/AssignMaterialCommand.cs", "body_location": {"start_line": 20, "end_line": 59}, "body": "public override void Execute(UIDocument uiDoc, Document doc)
        {
            ArgumentNullException.ThrowIfNull(uiDoc);
            ArgumentNullException.ThrowIfNull(doc);

            // 1. Resolve Service
            var service = ServiceLocator.GetRequiredService<MaterialAssignmentExecutionService>();

            // 2. Initialize VM & View
            var vm = ServiceLocator.GetRequiredService<AssignMaterialViewModel>();
            var preselectedRefs = SelectionSeedHelper.GetSelectedReferences(uiDoc, new SelectionFilters.MaterialHostFilter());
            if (preselectedRefs.Count > 0)
            {
                vm.SetSelection(preselectedRefs, doc);
            }

            // Pass VM explicitly so command and view share the same instance
            var view = ServiceLocator.CreateWith<AssignMaterialView>(vm);
            view.Initialize(uiDoc);

            // 3. Show Dialog
            bool? result = view.ShowDialog();

            // 4. Run Logic if Confirmed
            if (result == true && vm.ShouldRun && vm.SelectedRefs.Any())
            {
                ShowLogWindow("Assigning Materials...");

                // Convert References to Elements
                List<Element> elements = vm.SelectedRefs
                    .Select(r => doc.GetElement(r))
                    .Where(e => e != null)
                    .ToList();

                // Call Logic
                var reporter = new RevitCommandProgressReporter(_logger, UpdateProgress);
                service.AssignMaterialsToElements(doc, elements, reporter);
                UpdateProgress(100, "Complete");
            }
        }"}]

[{"name_path": "LECG.Services/MaterialAssignmentExecutionService/AssignMaterialsToElements", "kind": "Method", "relative_path": "src/Services/Materials/MaterialAssignmentExecutionService.cs", "body_location": {"start_line": 24, "end_line": 62}, "body": "public void AssignMaterialsToElements(Document doc, IList<Element> elements, IProgressReporter reporter)
        {
            ArgumentNullException.ThrowIfNull(doc);
            ArgumentNullException.ThrowIfNull(reporter);

            if (elements == null || !elements.Any()) return;

            reporter.Log("ANALYZING SELECTION");
            reporter.Report("Grouping by type...", 10);

            Dictionary<ElementId, List<Element>> elementsByType = _materialElementGroupingService.GroupByType(elements);

            reporter.Log($"Found {elementsByType.Count} unique types from {elements.Count} elements.");
            reporter.Log("");
            reporter.Log("CREATING/UPDATING MATERIALS");

            int processedTypes = 0;
            int totalTypes = elementsByType.Count;

            _transactionService.Run(doc, "Assign Material by Type", currentDoc =>
            {
                foreach (var kvp in elementsByType)
                {
                    processedTypes++;
                    double pct = 20 + processedTypes * 70.0 / totalTypes;

                    ElementType? elemType = currentDoc.GetElement(kvp.Key) as ElementType;
                    if (elemType == null) continue;

                    reporter.Report($"Processing: {elemType.Name}", pct);
                    _materialTypeAssignmentProcessService.TryProcess(currentDoc, elemType, kvp.Value.Count, reporter.Log);
                }
            });

            reporter.Log("");
            reporter.Log("COMPLETE");
            reporter.Log($"Processed {processedTypes} types.");
            reporter.Report("Done", 100);
        }"}]
